#!/usr/bin/env node
// Generates src/content/index.ts — the public barrel of every ported component.
// Canonical source of truth is the directory layout; run via `npm run gen:index`.
import { existsSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const contentDir = path.join(root, 'src', 'content')
const categories = ['Animations', 'Backgrounds', 'Components', 'Micro', 'TextAnimations']

const lines = [
  '// GENERATED by scripts/gen-index.mjs — do not edit by hand.',
  '// Regenerate with `npm run gen:index`.',
  '',
]

const seen = new Set()
let count = 0

for (const category of categories) {
  const categoryDir = path.join(contentDir, category)
  if (!existsSync(categoryDir)) continue
  for (const name of readdirSync(categoryDir).sort()) {
    const dir = path.join(categoryDir, name)
    const file = path.join(dir, `${name}.tsx`)
    if (!statSync(dir, { throwIfNoEntry: false })?.isDirectory()) continue
    if (!existsSync(file)) continue
    let id = name
    if (seen.has(id)) id = `${category}_${name}`
    if (seen.has(id)) continue
    seen.add(id)
    lines.push(`export { default as ${id} } from './${category}/${name}/${name}';`)
    count += 1
  }
}

lines.push('')
lines.push(`export const COMPONENT_COUNT = ${count};`)
lines.push('')

writeFileSync(path.join(contentDir, 'index.ts'), lines.join('\n'))
console.log(`gen-index: wrote src/content/index.ts (${count} components)`)
